package io.github.diodeme.ji.agent;

import io.github.diodeme.ji.ai.ModelProvider;
import io.github.diodeme.ji.extension.PermissionDecider;
import io.github.diodeme.ji.extension.ToolExecutionPolicy;
import io.github.diodeme.ji.extension.ToolInterceptor;
import io.github.diodeme.ji.extension.PromptAssembler;
import io.github.diodeme.ji.extension.PromptContributor;
import io.github.diodeme.ji.session.tree.SessionRepository;
import java.time.Clock;
import java.util.ArrayList;
import java.util.List;
import java.util.ServiceLoader;
import java.util.UUID;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/** Framework-free explicit builder for the embedded Agent runtime. */
public final class AgentRuntimeBuilder {
    private ModelProvider provider;
    private SessionRepository sessionRepository;
    private final List<ToolDefinition> tools = new ArrayList<>();
    private final List<PromptContributor> promptContributors = new ArrayList<>();
    private PromptAssembler.TokenCounter promptTokenCounter = text -> text.isBlank() ? 0 : (text.length() + 3) / 4;
    private int promptTokenBudget = 16_000;
    private String promptLocale = "en";
    private CompactionPolicy compactionPolicy = CompactionPolicy.manualOnly();
    private RuntimeConfiguration.IdGenerator idGenerator = scope -> scope + "-" + UUID.randomUUID();
    private Clock clock = Clock.systemUTC();
    private PermissionDecider permissionDecider = (request, cancellation) -> java.util.concurrent.CompletableFuture.completedFuture(
            new PermissionDecider.Decision(request.permissionId(), request.revision(), request.revision() + 1,
                    PermissionDecider.Outcome.DENY, clock.instant()));
    private ToolExecutionPolicy toolExecutionPolicy = context -> {
        ToolDefinition tool = tools.stream().filter(value -> value.schema().name().equals(context.toolName()))
                .findFirst().orElseThrow();
        return switch (tool.permissionMode()) {
            case ALLOW -> ToolExecutionPolicy.Evaluation.allow(tool.sequential(), "tool-definition");
            case ASK -> ToolExecutionPolicy.Evaluation.ask(tool.sequential(), "tool-definition");
            case DENY -> ToolExecutionPolicy.Evaluation.deny("tool-definition");
        };
    };
    private final List<ToolInterceptor> toolInterceptors = new ArrayList<>();
    private ExecutorService executor;

    public AgentRuntimeBuilder provider(ModelProvider value) { provider = value; return this; }
    public AgentRuntimeBuilder sessionRepository(SessionRepository value) { sessionRepository = value; return this; }
    public AgentRuntimeBuilder tool(ToolDefinition value) { tools.add(value); return this; }
    public AgentRuntimeBuilder promptContributor(PromptContributor value) { promptContributors.add(value); return this; }
    public AgentRuntimeBuilder promptTokenCounter(PromptAssembler.TokenCounter value) { promptTokenCounter = value; return this; }
    public AgentRuntimeBuilder promptTokenBudget(int value) { promptTokenBudget = value; return this; }
    public AgentRuntimeBuilder promptLocale(String value) { promptLocale = value; return this; }
    public AgentRuntimeBuilder compactionPolicy(CompactionPolicy value) { compactionPolicy = value; return this; }
    public AgentRuntimeBuilder permissionDecider(PermissionDecider value) { permissionDecider = value; return this; }
    public AgentRuntimeBuilder toolExecutionPolicy(ToolExecutionPolicy value) { toolExecutionPolicy = value; return this; }
    public AgentRuntimeBuilder toolInterceptor(ToolInterceptor value) { toolInterceptors.add(value); return this; }
    public AgentRuntimeBuilder idGenerator(RuntimeConfiguration.IdGenerator value) { idGenerator = value; return this; }
    public AgentRuntimeBuilder clock(Clock value) { clock = value; return this; }
    public AgentRuntimeBuilder executor(ExecutorService value) { executor = value; return this; }

    public AgentRuntime build() {
        if (provider == null) throw new IllegalStateException("provider is required");
        if (sessionRepository == null) throw new IllegalStateException("sessionRepository is required");
        var names = new java.util.HashSet<String>();
        for (ToolDefinition tool : tools) {
            if (!names.add(tool.schema().name())) throw new IllegalStateException("duplicate tool: " + tool.schema().name());
        }
        boolean ownsExecutor = executor == null;
        ExecutorService resolvedExecutor = ownsExecutor ? Executors.newThreadPerTaskExecutor(Thread.ofVirtual().name("ji-agent-", 0).factory()) : executor;
        var configuration = new RuntimeConfiguration(provider, sessionRepository, tools, promptContributors,
                promptTokenCounter, promptTokenBudget, promptLocale, compactionPolicy, permissionDecider,
                toolExecutionPolicy, toolInterceptors, idGenerator, clock, resolvedExecutor);
        AgentRuntimeFactory factory = ServiceLoader.load(AgentRuntimeFactory.class)
                .findFirst().orElseThrow(() -> new IllegalStateException("ji-agent-core is missing from the runtime classpath"));
        return factory.create(configuration, ownsExecutor);
    }

    /** Internal ServiceLoader seam that keeps implementation types out of the public builder. */
    public interface AgentRuntimeFactory {
        AgentRuntime create(RuntimeConfiguration configuration, boolean ownsExecutor);
    }
}
